EXPECTED = b'---\nname: infozip-fixture\ndescription: Inert fixture\n---\n'+b'Synthetic text.\n'*30


def extra(tag,payload):
    return struct.pack('<HH',tag,len(payload))+payload


def timestamp(flags=3, *, central=False, value=17):
    values = [value,29,41]
    raw = b''.join(struct.pack('<I',values[index]) for index in range(3)
                   if flags & (1<<index) and (not central or index==0))
    return extra(0x5455,bytes([flags])+raw)


def ownership(uid=b'\xff'*4,gid=b'\xff'*4):
    return extra(0x7875,b'\x01'+bytes([len(uid)])+uid+bytes([len(gid)])+gid)


def with_extras(local,central, *, made=0x031e,method=0):
    raw=archive(method=method);cd,end=locations(raw)
    local_head=bytearray(raw[:30]);nlen=struct.unpack_from('<H',raw,26)[0]
    struct.pack_into('<H',local_head,28,len(local))
    local_record=bytes(local_head)+raw[30:30+nlen]+local+raw[30+nlen:cd]
    central_head=bytearray(raw[cd:cd+46]);struct.pack_into('<H',central_head,30,len(central))
    struct.pack_into('<H',central_head,4,made)
    central_record=bytes(central_head)+raw[cd+46:end]+central
    eocd=bytearray(raw[end:]);struct.pack_into('<II',eocd,12,len(central_record),len(local_record))
    return local_record+central_record+bytes(eocd)


class InfoZipCompatibilityTests(unittest.TestCase):
    def fixture(self):
        fixture=importer.ImportTests(methodName='runTest');fixture.setUp();self.addCleanup(fixture.doCleanups)
        return fixture

    def test_exact_installed_default_stripped_and_stored_archives(self):
        for label,encoded in FIXTURES.items():
            with self.subTest(label=label):
                raw=base64.b64decode(encoded);plan=plan_archive(raw)
                self.assertEqual(plan.name,'infozip-fixture');self.assertEqual(plan.directories,())
                self.assertEqual([(f.path,f.data) for f in plan.files],[('SKILL.md',EXPECTED)])
                cd,_=locations(raw);self.assertEqual(raw[cd+4],30)
                self.assertEqual(raw[cd+6],10 if label=='store' else 20)

    def test_producer_version_is_not_required_feature_version(self):
        expected=plan_archive(archive())
        for maker in (0,10,20,30,63,255):
            with self.subTest(maker=maker):
                plan=plan_archive(with_extras(b'',b'',made=0x0300|maker,method=8))
                self.assertEqual((plan.name,plan.directories,plan.files,plan.total_bytes),
                                 (expected.name,expected.directories,expected.files,expected.total_bytes))
        for host in (1,2,10,19,255):
            with self.subTest(host=host),self.assertRaises(ValueError):plan_archive(with_extras(b'',b'',made=(host<<8)|30))
        for need in (0,11,21,45,63,255):
            raw=with_extras(b'',b'');cd,_=locations(raw)
            raw=change(change(raw,4,'<H',need),cd+6,'<H',need)
            with self.subTest(need=need),self.assertRaises(ValueError):plan_archive(raw)

    def test_all_timestamp_flags_use_local_lengths_and_central_projection(self):
        for flags in range(8):
            with self.subTest(flags=flags):
                raw=with_extras(timestamp(flags),timestamp(flags,central=True))
                self.assertEqual(plan_archive(raw).files[0].data,MD)
        # Signed timestamp bits are inert bytes, not date-converted or applied.
        raw=with_extras(timestamp(value=0xffffffff),timestamp(central=True,value=0xffffffff))
        self.assertEqual(plan_archive(raw).files[0].data,MD)

    def test_bounded_uid_gid_widths_and_extra_order(self):
        for uid_size in range(1,5):
            for gid_size in range(1,5):
                uid=ownership(b'\xff'*uid_size,b'\x80'*gid_size)
                self.assertEqual(plan_archive(with_extras(timestamp()+uid,uid+timestamp(central=True))).files[0].data,MD)
        local=timestamp(7)+ownership();central=timestamp(7,central=True)+ownership()
        self.assertEqual(len(local),MAX_EXTRA_BYTES)
        self.assertEqual(plan_archive(with_extras(local,central)).total_bytes,len(MD))

    def test_duplicate_unknown_and_filename_feature_override_extras_rejected(self):
        good=timestamp(1)
        for bad in (good+good,ownership()+ownership(),extra(0x7075,b'\x01name-override'),
                    extra(0x0001,b'\0'*16),extra(0x5855,b'\0'*8),extra(0x7855,b'\0'*4),
                    extra(0x756e,b'\0'*8),extra(0x9901,b'\0'*7),extra(0x9999,b'')):
            for local,central in ((bad,b''),(b'',bad),(bad,bad)):
                with self.subTest(bad=bad,local=bool(local)),self.assertRaises(ValueError):plan_archive(with_extras(local,central))

    def test_timestamp_reserved_bits_short_trailing_and_central_shape_rejected(self):
        bads=(extra(0x5455,b''),extra(0x5455,b'\x08'),extra(0x5455,b'\x01'),
              extra(0x5455,b'\x00'+b'\0'*4),extra(0x5455,b'\x01'+b'\0'*3),
              extra(0x5455,b'\x01'+b'\0'*5))
        for bad in bads:
            with self.subTest(bad=bad),self.assertRaises(ValueError):plan_archive(with_extras(bad,bad))
        # Local UT includes access time; that payload is invalid in central UT.
        with self.assertRaises(ValueError):plan_archive(with_extras(timestamp(3),timestamp(3)))

    def test_owner_version_width_truncation_and_tail_rejected(self):
        for payload in (b'',b'\x02\x01a\x01b',b'\x01\x00\x01b',b'\x01\x01a\x00',
                        b'\x01\x05aaaaa\x01b',b'\x01\x01a\x05bbbbb',b'\x01\x04ab',
                        b'\x01\x01a\x01',b'\x01\x01a\x01bc'):
            bad=extra(0x7875,payload)
            with self.subTest(payload=payload),self.assertRaises(ValueError):plan_archive(with_extras(bad,bad))

    def test_header_tag_sets_flags_and_common_values_must_agree(self):
        cases=((timestamp(1),b''),(b'',ownership()),(timestamp(3),timestamp(1)),
               (timestamp(1),timestamp(1,central=True,value=18)),
               (ownership(b'a',b'b'),ownership(b'a',b'c')),
               (ownership(b'a',b'b'),ownership(b'a\0',b'b')))
        for local,central in cases:
            with self.subTest(local=local,central=central),self.assertRaises(ValueError):plan_archive(with_extras(local,central))

    def test_tlv_boundaries_and_missing_header_bytes_rejected(self):
        for bad in (b'\x55',b'\x55\x54',b'\x55\x54\x01',b'\x55\x54\xff\xff',
                    timestamp(1)+b'\0',b'x'*(MAX_EXTRA_BYTES+1)):
            for local,central in ((bad,b''),(b'',bad)):
                with self.subTest(bad=bad,local=bool(local)),self.assertRaises(ValueError):plan_archive(with_extras(local,central))
        raw=with_extras(timestamp(),timestamp(central=True));cd,_=locations(raw)
        for position in (28,cd+30):
            with self.assertRaises(ValueError):plan_archive(change(raw,position,'<H',0xffff))

    def test_extras_do_not_weaken_crc_size_and_flag_checks(self):
        raw=with_extras(timestamp()+ownership(),timestamp(central=True)+ownership());cd,_=locations(raw)
        for position,fmt,value in ((14,'<I',0),(22,'<I',1),(cd+16,'<I',0),(cd+24,'<I',1),
                                   (6,'<H',8),(cd+8,'<H',1),(cd+10,'<H',12)):
            with self.subTest(position=position),self.assertRaises(ValueError):plan_archive(change(raw,position,fmt,value))
        with self.assertRaises(ValueError):plan_archive(raw.replace(MD,MD[:-1]+b'X'))

    def test_all_metadata_bytes_are_inert_but_archive_digest_is_exact(self):
        plain=plan_archive(archive(method=0))
        with_metadata=plan_archive(with_extras(timestamp()+ownership(),timestamp(central=True)+ownership()))
        self.assertEqual((plain.name,plain.directories,plain.files,plain.total_bytes),
                         (with_metadata.name,with_metadata.directories,with_metadata.files,with_metadata.total_bytes))
        self.assertNotEqual(plain.archive_sha256,with_metadata.archive_sha256)

    def test_actual_original_jwt_import_installs_no_archive_owner_modes_or_times(self):
        fixture=self.fixture()
        data=with_extras(timestamp()+ownership(),timestamp(central=True)+ownership());cd,_=locations(data)
        data=change(data,cd+38,'<I',0o100777<<16)
        with patch('os.chown',side_effect=AssertionError('No ownership restore')),\
             patch('os.chmod',side_effect=AssertionError('No mode restore')),\
             patch('os.utime',side_effect=AssertionError('No time restore')):
            self.assertEqual(fixture.request(data=data),(201,{'name':'imported-skill','files':1}))
        destination=fixture.root/'imported-skill/SKILL.md';info=destination.stat()
        self.assertEqual(destination.read_bytes(),MD);self.assertEqual(stat.S_IMODE(info.st_mode),0o600)
        self.assertEqual((info.st_uid,info.st_gid),(os.geteuid(),os.getegid()));self.assertNotEqual(int(info.st_mtime),17)
        self.assertEqual(stat.S_IMODE(destination.parent.stat().st_mode),0o700)

    def test_installed_infozip_default_archive_through_original_jwt(self):
        fixture=self.fixture();raw=base64.b64decode(FIXTURES['default'])
        self.assertEqual(fixture.request(data=raw),(201,{'name':'infozip-fixture','files':1}))
        self.assertEqual((fixture.root/'infozip-fixture/SKILL.md').read_bytes(),EXPECTED)
        self.assertEqual(fixture.request(data=raw)[0],409)

    def test_malformed_new_metadata_denied_before_filesystem(self):
        fixture=self.fixture()
        with patch('artex.server.skill_archive_import.ScopedFilesystem',side_effect=AssertionError('No filesystem access')):
            for local,central in ((timestamp(),timestamp()),(ownership(),b''),(b'\x55',b'')):
                self.assertEqual(fixture.request(data=with_extras(local,central))[0],400)
        self.assertEqual(list(fixture.root.iterdir()),[])

    def test_compatible_input_keeps_independent_grants_and_post_effect_unknown(self):
        fixture=self.fixture();raw=with_extras(timestamp()+ownership(),timestamp(central=True)+ownership())
        fixture.grants['import_']=False;self.assertEqual(fixture.request(data=raw)[0],403)
        fixture.grants['import_']=True
        with patch('artex.server.skill_archive_import.os.fsync',side_effect=OSError()):fixture.unknown(fixture.request(data=raw))
        self.assertEqual((fixture.root/'imported-skill/SKILL.md').read_bytes(),MD)
        self.assertEqual(fixture.request(data=raw)[0],409)

    def test_multiple_entries_directory_offsets_and_utf8_names_with_extras(self):
        for method in (zipfile.ZIP_STORED,zipfile.ZIP_DEFLATED):
            buf=io.BytesIO()
            with zipfile.ZipFile(buf,'w') as writer:
                for path,content in (('wrapper/',b''),('wrapper/SKILL.md',MD),
                                     ('wrapper/assets/',b''),('wrapper/assets/文.bin',b'\0\xff')):
                    entry=zipfile.ZipInfo(path);entry.create_version=30;entry.compress_type=method
                    entry.extra=timestamp(1)+ownership()
                    entry.external_attr=(0o40755<<16|0x10) if path.endswith('/') else 0o100644<<16
                    writer.writestr(entry,content)
            plan=plan_archive(buf.getvalue())
            self.assertEqual(plan.directories,('assets',));self.assertEqual(len(plan.files),2)
            self.assertEqual(plan.files[-1].data,b'\0\xff')
